package cn.zhuatech.collectionsai.controller; import cn.zhuatech.collectionsai.common.ApiResponse; import cn.zhuatech.collectionsai.dto.CollectionsAiDto.*; import cn.zhuatech.collectionsai.service.CollectionsAiService; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/admin") @PreAuthorize("hasAnyRole('DOMAIN_OPERATOR','QUALITY','ADMIN')") public class OperationsAdminController {private final CollectionsAiService service;public OperationsAdminController(CollectionsAiService service){this.service=service;}@GetMapping("/dashboard") public ApiResponse<Dashboard> dashboard(){return ApiResponse.ok(service.adminDashboard());}@GetMapping("/work-orders") public ApiResponse<List<WorkRecordView>> orders(){return ApiResponse.ok(service.workRecords());}}
